def _apply_saml_config_customizations():  # isort: skip
    """Route /vms/{id}/saml_config/ per the API contract.

    GET/POST/PATCH/DELETE all require ``idp_name`` as a query parameter.
    POST creates or modifies ``saml_settings``; PATCH (``remove_signed_certs``)
    removes signed-response requirements; the default SubEndpointResource
    read-update path incorrectly uses PATCH for create/modify.
    """
    from typing import Any, Dict

    from ansible_collections.vastdata.vms.plugins.module_utils.vast.client import RESTFailure
    from ansible_collections.vastdata.vms.plugins.module_utils.vast.diff import has_changes
    from ansible_collections.vastdata.vms.plugins.module_utils.vast.errors import VastAPIError, VastError

    # Survive ARGUMENT_SPEC regen: saml_settings can carry PEM keys/certs.
    ARGUMENT_SPEC.setdefault("saml_settings", {})["no_log"] = True

    VmsSamlConfig.module_result_key = "vms_saml_config"
    _QUERY_ONLY = frozenset({"idp_name", "remove_signed_certs"})
    _original_init = VmsSamlConfig.__init__

    def _missing_saml_config(exc: VastError) -> bool:
        """True when GET reports the IdP has no SAML config yet (API returns 400)."""
        if isinstance(exc, RESTFailure) and exc.status == 400:
            return "no saml config" in exc.body.lower()
        return False

    def _saml_init(self, module):
        _original_init(self, module)
        self._exclude.update(_QUERY_ONLY)

    def _idp_query(self) -> Dict[str, str]:
        return {"idp_name": self.params["idp_name"]}

    def _saml_get(self) -> Dict[str, Any]:
        try:
            return self._api_base.first(**_idp_query(self)) or {}
        except VastAPIError as e:
            if _missing_saml_config(e):
                return {}
            self.module.fail_json(msg=f"Failed to read {self.sub_path}: {e}")
        except VastError as e:
            self.module.fail_json(msg=f"Failed to read {self.sub_path}: {e}")

    def _saml_post(self, body: Dict[str, Any]) -> Any:
        try:
            return self._api_base.post(_query_params=_idp_query(self), **body)
        except VastAPIError as e:
            raise VastAPIError(f"Failed to create {self.sub_path}: {e}") from e

    def _saml_patch_remove_certs(self) -> Any:
        try:
            return self._api_base.patch(_query_params=_idp_query(self))
        except VastAPIError as e:
            raise VastAPIError(f"Failed to update {self.sub_path}: {e}") from e

    def _saml_delete(self) -> Any:
        try:
            return self._api_base.delete(_query_params=_idp_query(self))
        except VastAPIError as e:
            raise VastAPIError(f"Failed to delete {self.sub_path}: {e}") from e

    def _desired_settings(self) -> Dict[str, Any]:
        settings = self.params.get("saml_settings")
        return dict(settings) if isinstance(settings, dict) else {}

    def _project_current_settings(self, current: Dict[str, Any]) -> Dict[str, Any]:
        """Map GET /saml_config/ response fields back to ``saml_settings`` input shape."""
        projected: Dict[str, Any] = {}
        sp_settings = current.get("sp_settings")
        if isinstance(sp_settings, dict):
            for key in (
                "encrypt_assertion",
                "force_authn",
                "want_assertions_or_response_signed",
            ):
                if key in sp_settings:
                    projected[key] = sp_settings[key]
            # VMS often omits false defaults from GET; treat missing force_authn as false.
            projected.setdefault("force_authn", False)

        metadata = current.get("metadata")
        if isinstance(metadata, dict):
            remote = metadata.get("remote")
            if isinstance(remote, list) and remote and isinstance(remote[0], dict):
                url = remote[0].get("url")
                if url is not None:
                    projected["idp_metadata_url"] = url
            local = metadata.get("local")
            if local is not None:
                projected["idp_metadata"] = local

        idp = current.get("idp")
        if isinstance(idp, dict) and idp.get("entityid") is not None:
            projected["idp_entityid"] = idp["entityid"]

        return projected

    def _settings_changed(self, current: Dict[str, Any], desired: Dict[str, Any]) -> bool:
        if not desired:
            return False
        if not current:
            return True
        projected = self._project_current_settings(current)
        if not projected:
            return True
        comparable_keys = [key for key in desired if key in projected]
        if not comparable_keys:
            return False
        current_slice = {key: projected[key] for key in comparable_keys}
        desired_slice = {key: desired[key] for key in comparable_keys}
        return has_changes(current_slice, desired_slice, self.overrides)

    def _signed_certs_already_removed(self, current: Dict[str, Any]) -> bool:
        if not current:
            return True
        sp_settings = current.get("sp_settings")
        if not isinstance(sp_settings, dict):
            return True
        return not sp_settings.get("want_assertions_or_response_signed", False)

    def _saml_config_run(self) -> None:
        if self.params.get("remove_signed_certs") and self._desired_settings():
            self.module.fail_json(msg="remove_signed_certs cannot be combined with saml_settings")
        if self.params.get("remove_signed_certs"):
            if self.params.get("state") == "absent":
                self.module.fail_json(msg="remove_signed_certs cannot be used with state=absent")
            current = self.get()
            if self._signed_certs_already_removed(current):
                self.module.exit_json(changed=False, vms_saml_config=current or {})
            if self.check_mode:
                self.module.exit_json(changed=True, vms_saml_config=current or {})
            try:
                self._saml_patch_remove_certs()
            except VastAPIError as e:
                self.module.fail_json(msg=str(e))
            result = self.get() or {}
            self.module.exit_json(changed=True, vms_saml_config=result)
            return

        state = self.params.get("state", "present")

        if state == "absent":
            current = self.get()
            if not current:
                self.module.exit_json(changed=False, vms_saml_config={})
            if not self.check_mode:
                try:
                    self._saml_delete()
                except VastAPIError as e:
                    self.module.fail_json(msg=str(e))
            self.module.exit_json(changed=True, vms_saml_config={})
            return

        desired = self._desired_settings()
        current = self.get()

        if not desired:
            self.module.exit_json(changed=False, vms_saml_config=current or {})
            return

        changed = self._settings_changed(current, desired)
        diff_before = dict(current) if current else {}
        diff_after: Dict[str, Any] = {}
        result: Any = current or {}

        if changed and not self.check_mode:
            try:
                posted = self._saml_post({"saml_settings": desired})
                if isinstance(posted, dict) and posted:
                    result = posted
                else:
                    result = self.get() or desired
            except VastAPIError as e:
                self.module.fail_json(msg=str(e))
            diff_after = dict(result) if isinstance(result, dict) else {"saml_settings": desired}
        elif changed:
            diff_after = {**diff_before, **desired}
            result = diff_after

        output: Dict[str, Any] = {"changed": changed, "vms_saml_config": result}
        if changed:
            output["diff"] = {"before": diff_before, "after": diff_after}
        self.module.exit_json(**output)

    VmsSamlConfig.__init__ = _saml_init
    VmsSamlConfig.get = _saml_get
    VmsSamlConfig._saml_post = _saml_post
    VmsSamlConfig._saml_patch_remove_certs = _saml_patch_remove_certs
    VmsSamlConfig._saml_delete = _saml_delete
    VmsSamlConfig._desired_settings = _desired_settings
    VmsSamlConfig._project_current_settings = _project_current_settings
    VmsSamlConfig._settings_changed = _settings_changed
    VmsSamlConfig._signed_certs_already_removed = _signed_certs_already_removed
    VmsSamlConfig.run = _saml_config_run


_apply_saml_config_customizations()


